// a tiny parse for the keys these fixtures use (the service's `yaml` package lives in its image only)
function parse(t: string): any {
  const commands: Record<string, unknown> = {}, permissions: Record<string, unknown> = {};
  let sec = "";
  const top: Record<string, unknown> = {};
