#!/usr/bin/env node
"use strict";
// Image build step (Cyrus structure round, card 7): write <classpath dir>/<version>.members.json, the public API member index
// memberindex.js reads (names and signatures only: nothing from the jars is copied). Offline: javap over the already resolved
// classpath. usage: node gen-member-index.js <version> [classpath dir (default /opt/mb/classpath)] [app dir (default /opt/mb/app)]
const fs = require("fs");
const path = require("path");
const { execFileSync } = require("child_process");

const v = process.argv[2];
const dir = process.argv[3] || "/opt/mb/classpath";
const app = process.argv[4] || "/opt/mb/app";
if (!v) { console.error("usage: gen-member-index.js <version> [classpath dir] [app dir]"); process.exit(2); }
const { parseJavap } = require(path.join(app, "memberindex.js"));

const cp = fs.readFileSync(path.join(dir, `${v}.txt`), "utf8").trim();
const API = /^(org\/bukkit|io\/papermc\/paper|com\/destroystokyo\/paper|net\/kyori\/adventure\/(text|key|sound|audience|title|bossbar|inventory|nbt)|net\/md_5\/bungee\/api)\//;
const names = fs.readFileSync(path.join(dir, `${v}.classes.txt`), "utf8").split("\n")
  .filter((l) => l.endsWith(".class") && API.test(l) && !/(^|\/)(package-info|module-info)\.class$/.test(l))
  .map((l) => l.slice(0, -6).replace(/\//g, "."));
const classes = {};
const t0 = Date.now();
for (let i = 0; i < names.length; i += 120) {
  const batch = names.slice(i, i + 120);
  let out = "";
  try { out = execFileSync("javap", ["-public", "-cp", cp, ...batch], { encoding: "utf8", maxBuffer: 256 * 1024 * 1024, stdio: ["ignore", "pipe", "ignore"] }); }
  catch (e) { out = (e.stdout || "").toString(); }
  // one class per "Compiled from" header
  for (const chunk of out.split(/^Compiled from .*$/m)) {
    const p = parseJavap(chunk);
    if (p) classes[p.fqn] = p.rec;
  }
}
const file = path.join(dir, `${v}.members.json`);
fs.writeFileSync(file, JSON.stringify({ version: v, generated: "javap -public", classes }));
console.log(`${v}: ${Object.keys(classes).length} types of ${names.length} listed, ${fs.statSync(file).size} bytes, ${Date.now() - t0} ms`);
#!/bin/bash
# Generate the compile classpath for ONE pinned Minecraft 26.x Paper API coordinate, the same way the
# Dockerfile does for 1.21.x (Gradle resolving paper-api from repo.papermc.io), but on Java 25.
#   gen-classpath-26.sh <id> <paper-api-coordinate> [outdir]
#   e.g. JAVA25_HOME=/opt/mb/jdk25 GRADLE9_HOME=/opt/mb/gradle9 gen-classpath-26.sh 26.2 26.2.build.133-stable /opt/mb/classpath
# Writes <outdir>/<id>.txt          colon-joined absolute jar paths (identical format to the 1.21.x files)
