export const REMIX_POLICIES = ["OPEN", "CLOSED"] as const;
export type RemixPolicy = (typeof REMIX_POLICIES)[number];
/**
 * Default: OPEN. Every Cyrus mod already ships its full source under an open licence (MIT by
 * default), so anyone could rebuild it by hand; "OPEN" just makes that one click inside Cyrus and
 * keeps the credit chain intact. A creator who wants their page to stay theirs picks CLOSED.
 */
export const DEFAULT_REMIX_POLICY: RemixPolicy = "OPEN";
export const isRemixPolicy = (x: unknown): x is RemixPolicy => typeof x === "string" && (REMIX_POLICIES as readonly string[]).includes(x);

export const LISTING_LIMITS = {
  titleMin: 3,
  titleMax: CYRUS_TITLE_MAX,
  /** = the studio dialog's LISTING_DESCRIPTION_MAX (routing agent), so its brief description always fits. */
  taglineMax: 280,
  descriptionMax: 20_000,
  tags: 8,
  tagMin: 2,
  tagMax: 24,
  links: 6,
  linkLabelMax: 40,
  linkUrlMax: 300,
  changelogMax: 4000,
  photos: 12,
  captionMax: 140,
  imageBytes: 8 * 1024 * 1024,
};

export type ListingLink = { label: string; url: string };

/** What the editor (and the routing agent's post-forge dialog) sends. Every field is optional: only sent fields change. */
export type ModListingInput = {
  title?: string | null;
  /** The "brief description" shown under the title and on cards. */
  tagline?: string | null;
  /** Long description, markdown. */

// ── the listing editor ──────────────────────────────────────────────────────

/**
 * Save the creator's customisation of a Cyrus mod page. `projectIdOrBuildId` = the project's root
 * build id or any build of it. Only the fields present in `input` change.
 */
export async function saveModListing(projectIdOrBuildId: string, rawInput: ModListingInput | Record<string, unknown>): R<{ slug: string }> {
  const input = fromStudioListing(rawInput);
  const { user, allowed } = await requireViewer();
  if (!allowed || !user) return NF;
  const page = await ownProjectPage(projectIdOrBuildId, user);
  if (!page) return NF;
  const rl = checkRateLimit(`cyrus:listing:${user.id}`, { max: 40, windowMs: 10 * 60_000 });
  if (!rl.ok) return { error: `Saving a lot. Try again in ${rl.retryAfterSec}s.` };
  const doc = readModDoc(page.doc);
  const media = await cyrusDb.cyrusModMedia.findMany({ where: { pageId: page.id }, select: { id: true, kind: true } });
  const studio = rawInput !== input;
  // A category the studio dialog picked that this list doesn't know yet (merge: routing's universal ids) stays on the project.
  if (studio && input.category && !CATEGORIES.some((c) => c.key === input.category)) delete input.category;
  if (studio && input.iconMediaId && !media.some((m) => m.id === input.iconMediaId && m.kind === "icon")) delete input.iconMediaId;
  const v = validateListing(input, { versionIds: (doc?.versions ?? []).map((x) => x.buildId), categories: CATEGORIES.map((c) => c.key), media });
  if (!v.ok) return { error: v.error };
  const c = v.clean;
  const prev = await cyrusDb.cyrusModListing.findUnique({ where: { pageId: page.id } });

  const listingData: Prisma.CyrusModListingUncheckedCreateInput = { pageId: page.id, userId: user.id };
  if (c.tagline !== undefined) listingData.tagline = c.tagline;
  if (c.description !== undefined) listingData.description = c.description;
  if (c.category !== undefined) listingData.category = c.category;
  if (c.tags !== undefined) listingData.tags = c.tags;
  if (c.links !== undefined) listingData.links = c.links as unknown as Prisma.InputJsonValue;
  if (c.changelog !== undefined) listingData.changelog = c.changelog as unknown as Prisma.InputJsonValue;
  if (c.remixPolicy !== undefined) listingData.remixPolicy = c.remixPolicy;
  if (c.iconMediaId !== undefined) listingData.iconMediaId = c.iconMediaId;
  if (c.bannerMediaId !== undefined) listingData.bannerMediaId = c.bannerMediaId;
  const { pageId: _p, ...update } = listingData;
  void _p;

  const ops: Prisma.PrismaPromise<unknown>[] = [cyrusDb.cyrusModListing.upsert({ where: { pageId: page.id }, create: listingData, update })];
  const pageData: Prisma.CyrusModPageUpdateInput = {};
  if (c.title !== undefined) pageData.title = c.title;
  if (c.tagline !== undefined) pageData.tagline = c.tagline || doc?.tagline || null;
  if (c.visibility !== undefined) {
    pageData.visibility = c.visibility;
    if (c.visibility === "PUBLIC" && !page.publishedAt) pageData.publishedAt = new Date();
  }
  if (Object.keys(pageData).length) ops.push(cyrusDb.cyrusModPage.update({ where: { id: page.id }, data: pageData }));
  if (c.photoOrder) c.photoOrder.forEach((id, i) => ops.push(cyrusDb.cyrusModMedia.update({ where: { id }, data: { sort: i } })));
  if (c.captions) for (const [id, cap] of Object.entries(c.captions)) ops.push(cyrusDb.cyrusModMedia.update({ where: { id }, data: { caption: cap || null } }));
  // A replaced icon / banner is removed (the gallery keeps its own photos).
  for (const [field, kind] of [["iconMediaId", "icon"], ["bannerMediaId", "banner"]] as const) {
    if (c[field] !== undefined) ops.push(cyrusDb.cyrusModMedia.deleteMany({ where: { pageId: page.id, kind, ...(c[field] ? { id: { not: c[field]! } } : {}) } }));
  }
  if (c.title !== undefined) {
    const root = await cyrusDb.modBuild.findUnique({ where: { id: page.rootBuildId }, select: { cyrus: true } });
    const meta = applyProjectPatch(readCyrusMeta(root?.cyrus), { title: c.title });
    ops.push(cyrusDb.modBuild.update({ where: { id: page.rootBuildId }, data: { cyrus: meta as unknown as Prisma.InputJsonValue } }));
  }
  await cyrusDb.$transaction(ops);
  if (c.title !== undefined) await syncCyrusModPage(page.rootBuildId); // regenerates doc.name + the engine's GameMod name
  if (c.visibility === "PUBLIC") await ensureCreatorHandle(user.id).catch(() => null);
  await audit(user.id, "cyrusmods.listing", `${page.slug} ${Object.keys(c).join(",")}${prev ? "" : " (first)"}`);
  revalidate(page.slug);
  return { ok: true, slug: page.slug };
}

