const ctrl = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g;
const line = (s: unknown) => (typeof s === "string" ? s.replace(ctrl, "").replace(/[\r\n\t]+/g, " ").replace(/\s+/g, " ").trim() : "");
const text = (s: unknown) => (typeof s === "string" ? s.replace(ctrl, "").replace(/\r\n?/g, "\n").replace(/\n{4,}/g, "\n\n\n").trim() : "");
const idRe = /^[A-Za-z0-9_-]{1,64}$/;

/** "Boss Fights!" -> "boss-fights". Empty when nothing usable is left. */
export function normaliseTag(t: unknown): string {
  return line(t).toLowerCase().normalize("NFKD").replace(/[̀-ͯ]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, LISTING_LIMITS.tagMax).replace(/-+$/
}

