// Evidence levels for a build (method adoption, clean-room from the "evidence levels" idea): every verification a build
// carries is tagged with HOW it was obtained, and the portal shows the highest level that was really reached, in words,
// never a number. PURE and client-safe: it only reads records the portal already holds.
//
//   static      the jar compiled and the static checks (scan, ledger, asset checks) passed. Nothing ran.
//   synthetic   pre-flight: the plugin loaded inside a SIMULATED server (MockBukkit). Not a real server.
//   booted      Test Flight: a real Paper server booted with the plugin and enabled it (boot, plugins_enabled, clean log).
//   behaviour   a real server showed behaviour: commands answered, the behaviour oracle or the playtest bots passed
//               with evidence. Still not a game client.
//   client      a real game client loaded and showed it (resource pack, models). Nothing records this yet, so it can
//               only be reached when a record says so explicitly (registry resourcePackClientVerified, or a client flag).
//
// Rules: a rung is "reached" only with evidence; a skipped or not-run rung never counts; a failed rung is shown as failed.
// The highest level is the highest rung reached, but a failure on a LOWER rung caps it (a mod whose flight failed is not
// "synthetic" evidence just because pre-flight passed: the headline says the flight failed).

export const EVIDENCE_LEVELS = ["none", "static", "synthetic", "booted", "behaviour", "client"] as const;
export type EvidenceLevel = (typeof EVIDENCE_LEVELS)[number];
export type RungState = "reached" | "failed" | "not_run" | "not_available";
export type Rung = { level: Exclude<EvidenceLevel, "none">; state: RungState; basis: string };
export type EvidenceView = {
  highest: EvidenceLevel;
  /** One honest sentence for a badge / summary. */
  headline: string;
  rungs: Rung[];
  /** What would raise the level, in words (empty at the top). */
  next: string | null;
  /** A failed rung below the highest reached one, if any (the headline already says so). */
  failed: Exclude<EvidenceLevel, "none"> | null;
};

type Obj = Record<string, unknown>;
const obj = (v: unknown): Obj | null => (v && typeof v === "object" && !Array.isArray(v) ? (v as Obj) : null);
const str = (v: unknown) => (typeof v === "string" ? v : "");
const arr = (v: unknown): unknown[] => (Array.isArray(v) ? v : []);

export type EvidenceInput = {
  /** build.status */
  status?: string | null;
  /** build.result.preflight (MbPreflight) */
  preflight?: unknown;
  /** readCyrusMeta(build.cyrus).testFlight (StoredFlight) */
  testFlight?: unknown;
  /** true when the build's resource pack was loaded in a real client (nothing sets this today). */
  clientVerified?: boolean | null;
  /** The build's static findings were clean enough to ship (safety verdict is not "block"). */
  safetyOk?: boolean | null;
};

export function evidenceOf(i: EvidenceInput): EvidenceView {
  const rungs: Rung[] = [];
  const built = i.status === "succeeded";
  rungs.push({ level: "static", state: built && i.safetyOk !== false ? "reached" : built ? "failed" : "not_run", basis: built ? "Compiled and passed Nxeon's static checks. Nothing was run." : "No finished build." });

  const pf = obj(i.preflight);
  if (!pf) rungs.push({ level: "synthetic", state: "not_available", basis: "No pre-flight on record for this build." });
  else {
    const v = str(pf.verdict);
    const pass = v === "pass" && arr(pf.checks).some((c) => obj(c)?.status === "pass");
    rungs.push({ level: "synthetic", state: pass ? "reached" : v === "fail" ? "failed" : "not_run", basis: pass ? "Loaded inside a simulated server (MockBukkit); not a real server." : v === "fail" ? "The simulated-server load failed." : `Pre-flight ${v || "did not run"}.` });
  }

  const tf = obj(i.testFlight);
  const state = tf ? str(tf.state) : "";
  const verdict = tf ? str(tf.verdict) : "";
  const checks = arr(tf?.checks).map(obj).filter((c): c is Obj => !!c);
  const byId = (id: string) => checks.find((c) => c.id === id);
  const passedCheck = (id: string) => { const c = byId(id); return !!c && c.status === "pass"; };
  const flown = state === "done";
  const bootOk = flown && (verdict === "passed" || verdict === "passed_with_warnings") && (checks.length === 0 || (passedCheck("boot") || passedCheck("boot_done")) && (passedCheck("plugins_enabled") || checks.length === 0));
  if (!tf) rungs.push({ level: "booted", state: "not_run", basis: "No Test Flight on record." });
  else if (flown && verdict === "failed") rungs.push({ level: "booted", state: "failed", basis: str(tf.reason) || "The Test Flight failed." });
  else if (bootOk) rungs.push({ level: "booted", state: "reached", basis: `Booted on a real Paper server${str(tf.version) ? ` ${str(tf.version)}` : ""} with the plugin enabled.` });
  else rungs.push({ level: "booted", state: "not_run", basis: state === "queued" || state === "running" ? "The Test Flight has not finished." : str(tf.reason) || "The Test Flight did not complete." });

  // behaviour: the oracle's functional verdict, the playtest bots, or listed commands that answered on the flown server
  const fn = obj(tf?.functional);
  const fnPassed = !!fn && fn.verdict === "passed" && Number(obj(fn.counts)?.passed ?? 0) > 0;
  const fnFailed = !!fn && fn.verdict === "failed";
  const pt = obj(tf?.playtest);
  const ptPassed = !!pt && pt.verdict === "passed" && Number(obj(pt.counts)?.passed ?? 0) > 0;
  const ptFailed = !!pt && pt.verdict === "failed";
  const cmdCheck = checks.find((c) => c.id === "rcon_checks" || c.id === "commands");
  const cmdPassed = !!cmdCheck && cmdCheck.status === "pass";
  if (!bootOk) rungs.push({ level: "behaviour", state: tf ? "not_run" : "not_run", basis: "Needs a booted server first." });
  else if (fnFailed || ptFailed) rungs.push({ level: "behaviour", state: "failed", basis: fnFailed ? "Something the behaviour test tried did not work." : "A playtest bot step failed." });
  else if (fnPassed || ptPassed || cmdPassed) rungs.push({ level: "behaviour", state: "reached", basis: fnPassed ? "A test player tried the mod's behaviour on a real server and it worked." : ptPassed ? "Playtest bots ran scenarios on a real server and they passed." : "The mod's commands answered on a real server." });
  else rungs.push({ level: "behaviour", state: "not_run", basis: "No behaviour was exercised on the real server." });

  rungs.push(i.clientVerified === true
    ? { level: "client", state: "reached", basis: "Loaded in a real game client." }
    : { level: "client", state: "not_available", basis: "No real game client has been used to check this (textures, models and sounds are unseen)." });

  let highest: EvidenceLevel = "none";
  for (const r of rungs) if (r.state === "reached") highest = r.level;
  const failedRung = rungs.find((r) => r.state === "failed" && EVIDENCE_LEVELS.indexOf(r.level) > EVIDENCE_LEVELS.indexOf(highest)) ?? null;
  // a failed higher rung means the honest level is capped: never claim the lower one as the headline
  const failed = failedRung ? failedRung.level : null;
  const words: Record<EvidenceLevel, string> = {
    none: "Not verified: no build or check on record.",
    static: "Checked, not run: the plugin compiled and passed static checks, but was never started.",
    synthetic: "Loaded in a simulated server only: not tested on a real server.",
    booted: "Booted on a real server: it starts and enables; behaviour was not shown.",
    behaviour: "Behaviour shown on a real server: it did what was asked in the tests we ran. No game client was used.",
    client: "Shown in a real game client.",
  };
  const headline = failed ? `${words[highest]} A ${failed === "booted" ? "Test Flight" : failed === "behaviour" ? "behaviour" : failed} check FAILED.` : words[highest];
  const idx = EVIDENCE_LEVELS.indexOf(highest);
  const nextWords: Partial<Record<EvidenceLevel, string>> = {
    none: "Build the mod.", static: "Run the pre-flight and the Test Flight.", synthetic: "Run the Test Flight on a real server.",
    booted: "Run the behaviour test or list commands the Test Flight can try.", behaviour: "Look at it in a real game client (textures, models, sounds).",
  };
  return { highest, headline, rungs, next: idx < EVIDENCE_LEVELS.length - 1 ? nextWords[highest] ?? null : null, failed };
}

/** Compare two levels (for sorting and "at least" gates). */
export const levelAtLeast = (have: EvidenceLevel, need: EvidenceLevel) => EVIDENCE_LEVELS.indexOf(have) >= EVIDENCE_LEVELS.indexOf(need);
