import type { ModBuildView } from "../builder/types";
import { readCyrusMeta } from "../meta";
import { evidenceOf, type EvidenceLevel } from "../evidence/levels";

export type ModlogEntry = {
  buildId: string;
  /** "v1", "v2" ... in build order */
  label: string;
  at: string;
  status: ModBuildView["status"];
