  /** Notices the build raised (regressions, dropped assets, limitations): bounded. */
  notices: string[];
  evidence: { level: EvidenceLevel; headline: string };
};

const clip = (s: string, n: number) => { const t = String(s ?? "").replace(/\s+/g, " ").trim(); return t.length > n ? `${t.slice(0, n - 1).trimEnd()}…` : t; };

export function modlogEntry(b: ModBuildView, n: number): ModlogEntry {
  const r = b.result;
  const s = r?.summary;
  const led = r?.ledger;
  const d = led?.diff;
  const ev = evidenceOf({
    status: b.status, preflight: r?.preflight ?? null, testFlight: readCyrusMeta(b.cyrus).testFlight ?? null,
    safetyOk: r?.safety ? r.safety.verdict !== "block" : null,
  });
  return {
    buildId: b.id, label: `v${n}`, at: b.finishedAt || b.createdAt, status: b.status,
    what: clip(b.changeRequest || b.prompt, 240),
    why: b.changeRequest ? "Change requested by the owner" : "First build",
    result: clip(s?.changes || s?.tagline || (b.status === "failed" ? b.error || "This version did not build." : ""), 240),
    ledger: d ? { added: d.added.slice(0, 8), regressed: d.regressed.slice(0, 8), dropped: d.dropped.slice(0, 8), laneFlips: d.laneFlips.slice(0, 4), implemented: d.implemented } : null,
    notices: [...(led?.notices ?? []), ...(s?.limitations ?? [])].filter((x, i, a) => a.indexOf(x) === i).slice(0, 6).map((x) => clip(x, 200)),
    evidence: { level: ev.highest, headline: ev.headline },
  };
}

/** Oldest first, one entry per build of the chain. */
export function modlogOf(builds: ModBuildView[]): ModlogEntry[] {
  return [...builds].sort((a, b) => a.createdAt.localeCompare(b.createdAt)).map((b, i) => modlogEntry(b, i + 1));
}

/** Plain-text rendering for the Notes tab and exports. */
export function modlogText(entries: ModlogEntry[]): string {
  return entries.map((e) => {
    const lines = [`${e.label} (${e.at.slice(0, 10)}, build ${e.buildId}) ${e.status}`, `  Asked: ${e.what}`];
    if (e.result) lines.push(`  Changed: ${e.result}`);
    if (e.ledger) {
      if (e.ledger.added.length) lines.push(`  New: ${e.ledger.added.join("; ")}`);
      if (e.ledger.regressed.length) lines.push(`  Regressed: ${e.ledger.regressed.join("; ")}`);
      if (e.ledger.dropped.length) lines.push(`  Dropped: ${e.ledger.dropped.join("; ")}`);
    }
    lines.push(`  Evidence: ${e.evidence.level} - ${e.evidence.headline}`);
    return lines.join("\n");
  }).join("\n\n");
}
