// Publish-check lint (method adoption: "a lint, not legal advice"): runs before a mod page is made PUBLIC / featured.
// PURE. Deterministic, no model. Severity: "error" = a listed mod would be broken or misleading (blocks only in
// enforce mode); "warn" = worth fixing; "info" = FYI. By the owner's rule (warn, don't block) the default mode is warn.
//   CYRUS_PUBLISH_CHECK = off (default) | warn | enforce
import type { ModBuildResult } from "../builder/types";

export type PublishSeverity = "error" | "warn" | "info";
export type PublishFinding = { id: string; severity: PublishSeverity; message: string; fix: string; where?: string };
export type PublishReport = { ok: boolean; findings: PublishFinding[]; counts: Record<PublishSeverity, number>; checked: string[] };

export type PublishInput = {
  title: string;
  tagline?: string | null;
  description?: string | null;
  /** The head build's result (commands, permissions, config, warnings, files, summary, ledger). */
  result: Pick<ModBuildResult, "commands" | "permissions" | "config" | "warnings" | "files" | "summary" | "safety"> & { ledger?: ModBuildResult["ledger"]; preflight?: ModBuildResult["preflight"] } | null;
  /** plugin.yml `depend` + `softdepend` names (when known). */
  depends?: { hard: string[]; soft: string[] };
  /** Plugins Nxeon can provide / install for the buyer (managed deps). Default: BetterModel. */
  resolvable?: string[];
  /** This mod's reserved namespace (nx_xxxxxxxx) and plugin name. */
  namespace?: string | null;
  pluginName?: string | null;
  /** Other mods in the same listing scope (the creator's other listed pages), for duplicate detection. */
  others?: { pluginName?: string | null; namespace?: string | null; commands?: string[]; title?: string }[];
  /** Licence line shown on the page (the default MIT line counts) and credit lines for imported / library material. */
  licence?: string | null;
  credits?: string[];
  /** Third-party material the build used that requires credit (CC-BY library items, imports). */
  needsCredit?: boolean;
  /** Free-text corpus to scan for placeholders (messages, config defaults); optional. */
  extraText?: string[];
};

const PLACEHOLDER = [
  /\blorem ipsum\b/i, /\bTODO\b/, /\bFIXME\b/, /\bTBD\b/, /\bplaceholder\b/i, /\byour (?:text|message|name|description|server) here\b/i,
  /\bchange me\b/i, /\bexample\.com\b/i, /\bxxx+\b/i, /<(?:insert|your|todo)[^>]*>/i, /\[(?:insert|your|todo)[^\]]*\]/i, /\bfoo bar\b/i, /\bsample text\b/i,
];
const DEFAULT_RESOLVABLE = ["BetterModel", "Nxeon-PackLoader", "NxPackLoader"];
const norm = (s: string) => s.toLowerCase().replace(/^\//, "");

export function publishCheck(i: PublishInput): PublishReport {
  const f: PublishFinding[] = [];
  const add = (id: string, severity: PublishSeverity, message: string, fix: string, where?: string) => f.push({ id, severity, message, fix, ...(where ? { where } : {}) });
  const checked = ["commands_exist", "depend_resolved", "no_placeholder_text", "licence_credits", "config_documented", "no_duplicate_namespace", "built_and_safe"];
  const r = i.result;

  // 0. there is something to publish
  if (!r) add("built_and_safe", "error", "There is no finished build to publish.", "Build a version first.");
  else if (r.safety?.verdict === "block") add("built_and_safe", "error", "The safety check blocked this build.", "Fix the safety findings and rebuild before publishing.");

  // 1. every command the page or the build advertises exists in plugin.yml (and the ledger shows code behind it)
  if (r) {
    const declared = new Set(r.commands.map((c) => norm(c.usage.split(/\s+/)[0] || "")));
    const ledgerCmds = (r.ledger?.items ?? []).filter((x) => x.kind === "command");
    for (const it of ledgerCmds) {
      const name = norm(it.text.replace(/^\//, "").split(/\s+/)[0] || "");
      if (it.status === "dropped" || it.status === "regressed") add("commands_exist", "error", `The command /${name} was asked for but ${it.status === "dropped" ? "is not in this build" : "no longer works"}.`, `Rebuild so /${name} exists, or remove it from the description.`, `/${name}`);
    }
    const advertised = new Set<string>();
    for (const t of [i.tagline ?? "", i.description ?? ""]) for (const m of t.matchAll(/(?:^|[\s(`])\/([a-z][a-z0-9_-]{1,31})\b/gi)) advertised.add(m[1].toLowerCase());
    // a "/" followed by a word in prose can be a path or "and/or"; only flag names that look like commands and are not declared
    for (const a of advertised) if (!declared.has(a) && !/^(and|or|etc|s|n|the|a)$/.test(a) && !r.commands.some((c) => (c.usage || "").toLowerCase().includes(`/${a}`))) add("commands_exist", "warn", `The description mentions /${a}, which the plugin does not declare.`, `Add /${a} to the mod or remove the mention.`, `/${a}`);
    for (const c of r.commands) if (!String(c.description ?? "").trim()) add("commands_exist", "info", `/${norm(c.usage.split(/\s+/)[0] || "")} has no description in plugin.yml.`, "Add a short description so /help shows it.");
  }

  // 2. dependencies resolve
  const resolvable = new Set((i.resolvable ?? DEFAULT_RESOLVABLE).map((x) => x.toLowerCase()));
  for (const d of i.depends?.hard ?? []) if (!resolvable.has(d.toLowerCase())) add("depend_resolved", "error", `The plugin requires "${d}", which Nxeon cannot provide for the buyer.`, `Make "${d}" a soft dependency with a graceful fallback, or remove it.`, d);
  for (const d of i.depends?.soft ?? []) if (!resolvable.has(d.toLowerCase())) add("depend_resolved", "info", `Optional integration with "${d}": it is used only if the server already has it.`, `Say so on the page ("works with ${d} if installed").`, d);

  // 3. no placeholder text anywhere the buyer reads
  const texts: [string, string][] = [["title", i.title], ["tagline", i.tagline ?? ""], ["description", i.description ?? ""], ...(i.extraText ?? []).map((t, n) => [`text ${n + 1}`, t] as [string, string])];
  if (r) {
    for (const c of r.commands) texts.push([`command ${c.usage}`, c.description ?? ""]);
    for (const c of r.config) texts.push([`config ${c.key}`, c.description ?? ""]);
    if (r.summary) { texts.push(["summary", r.summary.text ?? ""]); for (const h of r.summary.howToUse ?? []) texts.push(["how to use", h]); }
  }
  for (const [where, t] of texts) {
    for (const re of PLACEHOLDER) { const m = re.exec(t); if (m) { add("no_placeholder_text", "error", `Placeholder text in ${where}: "${m[0]}".`, "Replace it with real text before publishing.", where); break; } }
  }
  if (!String(i.title).trim() || String(i.title).trim().length < 3) add("no_placeholder_text", "error", "The mod has no real title.", "Give it a name of at least 3 characters.", "title");
  if (!String(i.tagline ?? "").trim() && !String(i.description ?? "").trim()) add("no_placeholder_text", "warn", "The page has no description.", "Write one or two sentences about what the mod does.", "description");

  // 4. licence and credit lines
  if (!String(i.licence ?? "").trim()) add("licence_credits", "warn", "No licence line is set.", "Cyrus mods default to MIT; say so on the page or pick another licence.");
  if (i.needsCredit && !(i.credits ?? []).some((c) => c.trim())) add("licence_credits", "error", "The build uses material that requires credit, but the page has no credit line.", "Add the credit lines (creator, source, licence) to the description.");

  // 5. config documented
  if (r) {
    const undocumented = r.config.filter((c) => !String(c.description ?? "").trim());
    if (undocumented.length) add("config_documented", "warn", `${undocumented.length} config key${undocumented.length > 1 ? "s have" : " has"} no description (${undocumented.slice(0, 4).map((c) => c.key).join(", ")}${undocumented.length > 4 ? ", ..." : ""}).`, "Describe each key in config.yml comments or the build summary.");
    if (!r.config.length && (r.files ?? []).some((x) => /config\.yml$/.test(x.path))) add("config_documented", "info", "The plugin ships config.yml but the build listed no documented keys.", "List the keys and what they do.");
  }

  // 6. no duplicate namespace / names
  for (const o of i.others ?? []) {
    if (i.namespace && o.namespace && i.namespace === o.namespace) add("no_duplicate_namespace", "error", `Another listed mod uses the same namespace (${i.namespace}).`, "Namespaces are per project; this is a copy or a mix-up. Rebuild under its own project.", i.namespace);
    if (i.pluginName && o.pluginName && i.pluginName.toLowerCase() === o.pluginName.toLowerCase()) add("no_duplicate_namespace", "warn", `Another listed mod has the same plugin name "${i.pluginName}"; both cannot be installed on one server.`, "Give this plugin a distinct name.", i.pluginName);
    const mine = new Set((r?.commands ?? []).map((c) => norm(c.usage.split(/\s+/)[0] || "")));
    const clash = (o.commands ?? []).map(norm).filter((c) => c && mine.has(c));
    if (clash.length) add("no_duplicate_namespace", "info", `Command name clash with "${o.title ?? o.pluginName ?? "another mod"}": ${clash.slice(0, 4).map((c) => "/" + c).join(", ")}.`, "Pick a distinct command name or prefix, or note that the mods conflict.");
  }

  const counts = { error: 0, warn: 0, info: 0 } as Record<PublishSeverity, number>;
  for (const x of f) counts[x.severity]++;
  return { ok: counts.error === 0, findings: f, counts, checked };
}

export type PublishCheckMode = "off" | "warn" | "enforce";
export function publishCheckMode(env: Record<string, string | undefined> = process.env): PublishCheckMode {
  const v = String(env.CYRUS_PUBLISH_CHECK ?? "").toLowerCase();
  return v === "enforce" ? "enforce" : v === "warn" || v === "1" || v === "on" ? "warn" : "off";
}
/** Does this report stop a listing in this mode? Only errors, only in enforce. */
export const publishBlocks = (mode: PublishCheckMode, r: PublishReport) => mode === "enforce" && !r.ok;
