cd /tank/dev-worktrees/cyrus-engine2; cat > test/cyrus-engine2-method.test.ts <<'EOF'
// Method adoption (engine2): evidence levels, MODLOG, publish-check lint. Pure, offline, no DB.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { evidenceOf, levelAtLeast } from "../lib/cyrus/evidence/levels";
import { modlogEntry, modlogOf, modlogText } from "../lib/cyrus/modlog/modlog";
import { publishBlocks, publishCheck, publishCheckMode } from "../lib/cyrus/safety/publish-check";
import type { ModBuildView } from "../lib/cyrus/builder/types";

const flight = (over: Record<string, unknown> = {}) => ({
  state: "done", verdict: "passed", version: "1.21.11",
  checks: [{ id: "boot", status: "pass" }, { id: "plugins_enabled", status: "pass" }, { id: "commands", status: "not_run" }], ...over,
});
const pre = (verdict: string) => ({ verdict, evidence: "synthetic", checks: [{ id: "load", status: verdict === "pass" ? "pass" : "fail", detail: "" }] });

describe("evidence levels", () => {
  it("a built jar with nothing run is 'static', never more", () => {
    const e = evidenceOf({ status: "succeeded" });
    assert.equal(e.highest, "static");
    assert.match(e.headline, /never started/);
    assert.equal(e.rungs.find((r) => r.level === "client")!.state, "not_available");
  });
  it("pre-flight only is synthetic, with the simulated-server wording", () => {
    const e = evidenceOf({ status: "succeeded", preflight: pre("pass") });
    assert.equal(e.highest, "synthetic");
    assert.match(e.headline, /simulated server only/);
  });
  it("a passed flight is booted, not behaviour", () => {
    const e = evidenceOf({ status: "succeeded", preflight: pre("pass"), testFlight: flight() });
    assert.equal(e.highest, "booted");
    assert.match(e.next ?? "", /behaviour/);
  });
  it("behaviour needs the oracle, the playtest or answered commands WITH passes", () => {
    assert.equal(evidenceOf({ status: "succeeded", testFlight: flight({ functional: { verdict: "passed", counts: { passed: 3, failed: 0, total: 3 } } }) }).highest, "behaviour");
    assert.equal(evidenceOf({ status: "succeeded", testFlight: flight({ playtest: { verdict: "passed", counts: { passed: 2 } } }) }).highest, "behaviour");
    // zero passed is not evidence
    assert.equal(evidenceOf({ status: "succeeded", testFlight: flight({ functional: { verdict: "passed", counts: { passed: 0, failed: 0, total: 0 } } }) }).highest, "booted");
    // a not_run oracle never counts
    assert.equal(evidenceOf({ status: "succeeded", testFlight: flight({ functional: { verdict: "not_run", counts: { passed: 0 } } }) }).highest, "booted");
  });
  it("a failed flight is reported as failed and does not lift the level; synthetic pass stays honest", () => {
    const e = evidenceOf({ status: "succeeded", preflight: pre("pass"), testFlight: flight({ verdict: "failed", reason: "plugins_enabled failed" }) });
    assert.equal(e.highest, "synthetic");
    assert.equal(e.failed, "booted");
    assert.match(e.headline, /FAILED/);
  });
  it("a failed behaviour step after a boot is shown as failed on the behaviour rung", () => {
    const e = evidenceOf({ status: "succeeded", testFlight: flight({ functional: { verdict: "failed", counts: { passed: 1, failed: 1, total: 2 } } }) });
    assert.equal(e.highest, "booted");
    assert.equal(e.failed, "behaviour");
  });
  it("queued / running flights are not evidence", () => {
    assert.equal(evidenceOf({ status: "succeeded", testFlight: { state: "queued", verdict: "" } }).highest, "static");
    assert.equal(evidenceOf({ status: "succeeded", testFlight: { state: "running", verdict: "" } }).highest, "static");
  });
  it("failed or in-progress builds are 'none'", () => {
    assert.equal(evidenceOf({ status: "failed" }).highest, "none");
    assert.equal(evidenceOf({ status: "coding" }).highest, "none");
  });
  it("client level is reached only on an explicit client record", () => {
    assert.equal(evidenceOf({ status: "succeeded", testFlight: flight(), clientVerified: true }).highest, "client");
    assert.equal(levelAtLeast("behaviour", "booted"), true);
    assert.equal(levelAtLeast("synthetic", "booted"), false);
  });
});

const build = (id: string, createdAt: string, over: Partial<ModBuildView> = {}): ModBuildView => ({
  id, status: "succeeded", prompt: "make a fire sword", changeRequest: null, baseBuildId: null, rootBuildId: "r1", mcVersion: "1.21.11",
  pluginName: "Fire", version: "1.0.0", error: null, errorCode: null, attempts: 1, durationMs: 1000, jarName: "Fire.jar", jarSize: 100,
  createdAt, finishedAt: createdAt, result: null, lastInstall: null, cyrus: null, ...over,
} as ModBuildView);

describe("MODLOG", () => {
  it("one entry per build, oldest first, with what / why / evidence", () => {
    const log = modlogOf([
      build("b2", "2026-10-02T00:00:00Z", { changeRequest: "add a cooldown", prompt: "ignored" }),
      build("b1", "2026-10-01T00:00:00Z"),
    ]);
    assert.deepEqual(log.map((e) => e.buildId), ["b1", "b2"]);
    assert.equal(log[0].why, "First build");
    assert.equal(log[1].why, "Change requested by the owner");
    assert.equal(log[1].what, "add a cooldown");
    assert.equal(log[0].evidence.level, "static");
  });
  it("is append-only by construction: an older entry does not change when a newer build is added", () => {
    const b1 = build("b1", "2026-10-01T00:00:00Z");
    const before = JSON.stringify(modlogOf([b1])[0]);
    const after = JSON.stringify(modlogOf([b1, build("b2", "2026-10-02T00:00:00Z", { changeRequest: "x" })])[0]);
    assert.equal(before, after);
  });
  it("carries the ledger diff and notices from the build result", () => {
    const e = modlogEntry(build("b3", "2026-10-03T00:00:00Z", {
      changeRequest: "remove the dash",
      result: { summary: { tagline: "t", text: "", howToUse: [], limitations: ["No model yet."], changes: "Removed the dash." }, commands: [], permissions: [], config: [], warnings: [], files: [], safety: null, events: [], repairs: 0, queuePosition: 0,
        ledger: { version: 1, lineage: "r1", builds: ["b2", "b3"], items: [], notices: ["The command /dash no longer works."], evidence: "static", diff: { regressed: ["/dash"], dropped: [], laneFlips: [], added: ["cooldown"], implemented: 4 } } } as unknown as ModBuildView["result"],
    }), 3);
    assert.equal(e.label, "v3");
    assert.deepEqual(e.ledger?.regressed, ["/dash"]);
    assert.match(e.notices.join(" "), /no longer works/);
    assert.match(modlogText([e]), /Regressed: \/dash/);
  });
});

const baseResult = (over: Record<string, unknown> = {}) => ({
  summary: { tagline: "A fire sword", text: "Adds a fire sword.", howToUse: ["Hold it and right click."], limitations: [], changes: "" },
  commands: [{ usage: "/firesword give", description: "Gives the sword", permission: null }],
  permissions: [], config: [{ key: "cooldown", description: "Seconds between uses", default: "5" }],
  warnings: [], files: [{ path: "src/Main.java", size: 10 }], safety: { verdict: "pass", findings: [] }, ...over,
}) as never;

describe("publish-check lint", () => {
  it("a clean mod passes with no errors", () => {
    const r = publishCheck({ title: "Fire Sword", tagline: "Right click for a fireball. Use /firesword give.", description: null, result: baseResult(), licence: "MIT" });
    assert.equal(r.ok, true, JSON.stringify(r.findings));
    assert.equal(r.counts.error, 0);
  });
  it("flags placeholder text, undocumented config and an undeclared advertised command", () => {
    const r = publishCheck({
      title: "My Mod", tagline: "TODO write a description. Try /fireball", result: baseResult({ config: [{ key: "x", description: "", default: "1" }] }), licence: "MIT",
    });
    const ids = r.findings.map((f) => f.id + ":" + f.severity);
    assert.ok(ids.includes("no_placeholder_text:error"));
    assert.ok(ids.includes("config_documented:warn"));
    assert.ok(ids.includes("commands_exist:warn"));
    assert.equal(r.ok, false);
  });
  it("hard dependencies Nxeon cannot provide are errors; soft ones are info", () => {
    const r = publishCheck({ title: "Shop", tagline: "A shop", result: baseResult(), licence: "MIT", depends: { hard: ["Vault"], soft: ["PlaceholderAPI"] } });
    assert.equal(r.findings.find((f) => f.where === "Vault")?.severity, "error");
    assert.equal(r.findings.find((f) => f.where === "PlaceholderAPI")?.severity, "info");
