"use strict";
// Cyrus build-service PRE-FLIGHT (card 3). Runs right after a build compiles and passes the safety scan, before the async
// Test Flight: loads the compiled jar into MockBukkit (tools/preflight/Preflight.java, one throwaway JVM, offline, a wall-clock
// budget) and asserts plugin.yml parses, the main class loads, onEnable completes, declared commands are registered and run with
// a mock sender, declared permissions register, and depend/softdepend resolve (managed engine plugins are stubbed with an
// absent-class guard, so a creature plugin is "needs engine", not "crashed").
//
// Rules this module holds to:
//   * Honest: anything MockBukkit cannot model (UnimplementedOperationException, an unsupported Minecraft version, harness errors)
//     is `skipped`, never `pass` and never `fail`. Test Flight stays the real gate.
//   * Isolated: run() never throws and never rejects; an infrastructure error returns verdict "skipped" with a reason and the
//     build continues. Hard timeout, small heap, no network (the container firewall) and a minimal environment (no AI keys).
//   * Deterministic first: a failure is offered to mechanicalFixes() (no model turn) before it becomes a repair-loop problem.
//
// Env: MB_PREFLIGHT = advise (DEFAULT for the first deploy, rc15: record only, never a repair) | 1 / enforce (a definite failure is fixed / repaired) | 0/off
//      MB_PREFLIGHT_DIR (default /opt/mb/preflight: preflight.jar + mock.txt), MB_PREFLIGHT_VERSIONS (default "1.21.11":
//      MockBukkit v1.21 4.116.3 needs the 1.21.9+ API; older Paper APIs fail MockBukkit.mock() and are skipped up front),
//      MB_PREFLIGHT_BUDGET_MS (default 15000), MB_PREFLIGHT_JAVA (default `java`).
const fs = require("fs");
const os = require("os");
const path = require("path");
const { spawn } = require("child_process");

const MOCKBUKKIT_VERSION = "4.116.3";
const MOCKBUKKIT_ARTIFACT = "org.mockbukkit.mockbukkit:mockbukkit-v1.21";

function envOf(env) { return env || process.env; }
function mode(env) {
  const v = String(envOf(env).MB_PREFLIGHT === undefined ? "advise" : envOf(env).MB_PREFLIGHT).toLowerCase();
  if (v === "0" || v === "off" || v === "false" || v === "no") return "off";
  if (v === "1" || v === "enforce" || v === "on" || v === "true" || v === "yes") return "enforce";
