function ready(mcVersion, env, cpDir) {
  if (mode(env) === "off") return { ok: false, reason: "switched off (MB_PREFLIGHT=0)" };
  if (!supportedVersions(env).includes(String(mcVersion))) return { ok: false, reason: `MockBukkit ${MOCKBUKKIT_VERSION} does not cover Minecraft ${mcVersion}` };
  const d = dirOf(env);
  for (const f of [path.join(d, "preflight.jar"), path.join(d, "mock.txt"), path.join(cpDir || "/opt/mb/classpath", `${mcVersion}.txt`)]) {
    if (!fs.existsSync(f)) return { ok: false, reason: `pre-flight files are not in this image (${path.basename(f)})` };
  }
  return { ok: true, reason: null };
}

