// Live-test fix (E): the version list every picker shows (pure, client-safe): every registry version of a game, its
// loader and status, whether Cyrus can build it (and why not), a one-line capability note, and the full "what this
// version supports" panel from the game's capability catalogue (lib/cyrus/adapters/capabilities.ts).
import { getAdapter } from "../adapters";
import { resolveCapabilities, type LaneCapability } from "../adapters/capabilities";
import { LANE_META } from "../planner/lanes";

export type VersionChoice = {
  id: string;
  loader: string;
  status: string;
  buildable: boolean;
  /** Why it cannot be picked (null when buildable). */
  reason: string | null;
  /** One line: the most important difference of this version. */
  note: string;
  lanes: LaneCapability[];
};

const LOADER: Record<string, string> = { minecraft: "Paper" };

function noteFor(lanes: LaneCapability[], id: string): string {
  const tex = lanes.find((l) => l.lane === "texture");
  const cre = lanes.find((l) => l.lane === "creature");
  if (tex?.availability === "limited") return `Custom textures use the legacy path (custom model data on a vanilla carrier); no per-state looks.`;
  if (tex?.availability === "unavailable" && tex.cause === "version") return `No custom textures on ${id} (needs ${tex.minVersion ?? "a newer version"}).`;
  if (cre?.availability === "available") return "Animated custom creatures (BetterModel).";
  return "Custom textures, sounds, designers; mob skins need 26.x.";
}

export function versionChoices(game: string, flags: Record<string, boolean>): VersionChoice[] {
  const a = getAdapter(game);
  if (!a) return [];
  const all = [...a.versions.list()];
  // buildable ones first (newest first), then the ones Cyrus cannot build yet (previews), oldest preview first
  const ordered = [...all.filter((v) => v.buildable).reverse(), ...all.filter((v) => !v.buildable)];
  return ordered.map((v) => {
    const lanes = resolveCapabilities(a.capabilities, { game, gameName: a.name, version: v.id, hasCapability: (c) => a.versions.hasCapability(v.id, c), flags });
    const reason = v.buildable ? null : v.status === "preview" ? "Preview: not buildable yet" : v.status === "blocked" ? "Blocked: Cyrus cannot build for it" : "Not buildable yet";
    return { id: v.id, loader: LOADER[game] ?? a.name, status: v.status, buildable: v.buildable, reason, note: noteFor(lanes, v.id), lanes };
  });
}

export const laneLabel = (l: LaneCapability["lane"]) => LANE_META[l].label;

